-- Pronoia schema v1 (docs/design/04-store-schema.md).
-- Every device-owned table carries tenant_id (ADR-015). IDs are UUIDv7 generated by the application.

CREATE TABLE tenants (
    id          uuid PRIMARY KEY,
    name        text NOT NULL UNIQUE,
    created_at  timestamptz NOT NULL DEFAULT now()
);

INSERT INTO tenants (id, name) VALUES ('00000000-0000-0000-0000-000000000001', 'default');

CREATE TABLE devices (
    id                      uuid PRIMARY KEY,
    tenant_id               uuid NOT NULL REFERENCES tenants (id),
    protocol                text NOT NULL CHECK (protocol IN ('cwmp', 'usp')),
    -- CWMP identity (DeviceId of Inform); also filled for USP devices from DeviceInfo.
    oui                     text,
    product_class           text NOT NULL DEFAULT '',
    serial_number           text,
    -- USP identity.
    endpoint_id             text,
    manufacturer            text,
    model_name              text,
    software_version        text,
    hardware_version        text,
    data_model              text,
    connection_request_url  text,
    cwmp_version            text,
    status                  text NOT NULL DEFAULT 'active'
                            CHECK (status IN ('active', 'quarantined', 'retired')),
    tags                    text[] NOT NULL DEFAULT '{}',
    first_seen_at           timestamptz NOT NULL DEFAULT now(),
    last_contact_at         timestamptz,
    last_boot_at            timestamptz,
    last_remote_addr        inet,
    CHECK (
        (protocol = 'cwmp' AND oui IS NOT NULL AND serial_number IS NOT NULL)
        OR (protocol = 'usp' AND endpoint_id IS NOT NULL)
    )
);

CREATE UNIQUE INDEX devices_cwmp_identity
    ON devices (tenant_id, oui, product_class, serial_number) WHERE protocol = 'cwmp';
CREATE UNIQUE INDEX devices_usp_identity
    ON devices (tenant_id, endpoint_id) WHERE protocol = 'usp';
CREATE INDEX devices_tags ON devices USING gin (tags);
CREATE INDEX devices_last_contact ON devices (tenant_id, last_contact_at DESC);

-- Latest known parameter values, one row per path (ADR-027).
CREATE TABLE device_params (
    device_id   uuid NOT NULL REFERENCES devices (id) ON DELETE CASCADE,
    path        text NOT NULL,
    value       text,              -- NULL: name known, value not fetched yet
    xsd_type    text,
    writable    boolean,
    updated_at  timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (device_id, path)
);

CREATE INDEX device_params_path_value ON device_params (path, value);

-- User-defined attributes and external IDs (CO-13).
CREATE TABLE device_attributes (
    device_id  uuid NOT NULL REFERENCES devices (id) ON DELETE CASCADE,
    key        text NOT NULL,
    value      text NOT NULL,
    PRIMARY KEY (device_id, key)
);

CREATE INDEX device_attributes_kv ON device_attributes (key, value);

-- Persistent task queue (CO-02).
CREATE TABLE tasks (
    id               uuid PRIMARY KEY,
    tenant_id        uuid NOT NULL REFERENCES tenants (id),
    device_id        uuid NOT NULL REFERENCES devices (id) ON DELETE CASCADE,
    kind             text NOT NULL,
    payload          jsonb NOT NULL DEFAULT '{}',
    state            text NOT NULL DEFAULT 'pending'
                     CHECK (state IN ('pending', 'running', 'succeeded', 'failed', 'cancelled', 'expired')),
    priority         smallint NOT NULL DEFAULT 0,
    attempts         integer NOT NULL DEFAULT 0,
    max_attempts     integer NOT NULL DEFAULT 3 CHECK (max_attempts > 0),
    idempotency_key  text,
    result           jsonb,
    error            text,
    created_by       text,
    created_at       timestamptz NOT NULL DEFAULT now(),
    not_before       timestamptz,
    expires_at       timestamptz,
    started_at       timestamptz,
    finished_at      timestamptz
);

CREATE INDEX tasks_pending ON tasks (device_id, priority DESC, created_at) WHERE state = 'pending';
CREATE INDEX tasks_running ON tasks (device_id) WHERE state = 'running';
CREATE UNIQUE INDEX tasks_idempotency
    ON tasks (tenant_id, idempotency_key) WHERE idempotency_key IS NOT NULL;

CREATE TABLE events (
    id           bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    tenant_id    uuid NOT NULL REFERENCES tenants (id),
    device_id    uuid REFERENCES devices (id) ON DELETE CASCADE,
    kind         text NOT NULL,
    detail       jsonb NOT NULL DEFAULT '{}',
    occurred_at  timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX events_device_time ON events (device_id, occurred_at DESC);
CREATE INDEX events_tenant_time ON events (tenant_id, occurred_at DESC);

-- Firmware and configuration files served to devices (CW-16).
CREATE TABLE files (
    id                uuid PRIMARY KEY,
    tenant_id         uuid NOT NULL REFERENCES tenants (id),
    name              text NOT NULL,
    file_type         text NOT NULL,
    size_bytes        bigint NOT NULL CHECK (size_bytes >= 0),
    sha256            bytea NOT NULL,
    storage_key       text NOT NULL,
    target_oui        text,
    target_product_class text,
    version           text,
    created_at        timestamptz NOT NULL DEFAULT now(),
    UNIQUE (tenant_id, name)
);

-- Device secrets, encrypted at rest; plaintext is never stored (CO-16).
CREATE TABLE device_credentials (
    device_id          uuid NOT NULL REFERENCES devices (id) ON DELETE CASCADE,
    kind               text NOT NULL CHECK (kind IN ('acs_auth', 'connection_request')),
    username           text NOT NULL,
    secret_ciphertext  bytea NOT NULL,
    nonce              bytea NOT NULL,
    key_id             text NOT NULL,
    rotated_at         timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (device_id, kind)
);

CREATE TABLE audit_log (
    id           bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    tenant_id    uuid NOT NULL REFERENCES tenants (id),
    actor        text NOT NULL,
    action       text NOT NULL,
    target_type  text NOT NULL,
    target_id    text,
    detail       jsonb NOT NULL DEFAULT '{}',
    occurred_at  timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX audit_log_tenant_time ON audit_log (tenant_id, occurred_at DESC);
